"""Generates traffic_unicode_tables.go: CPython 3.11's str.lower() data
(Unicode 14.0) for metrics.pyLower — the full lowercase mapping and the
case-ignorable / cased sets of the final sigma rule. Go's unicode tables are
newer (they lower letters added after Unicode 14) and its IsUpper/IsLower
miss Other_Lowercase / Other_Uppercase (ª, Ⅰ, Ⓐ, …), so the tables are taken
from Python.

    rt --back server/internal/agents/metrics/traffic_unicode_tables.go -- bash -lc '~/cf-test/.venv/bin/python -I server/internal/agents/metrics/testdata/gen_a05_unicode_tables.py | (cd server && gofmt) > server/internal/agents/metrics/traffic_unicode_tables.go'
"""
import sys
import unicodedata

assert sys.version_info[:2] == (3, 11), sys.version


def chars():
    for cp in range(0x110000):
        if not 0xD800 <= cp <= 0xDFFF:
            yield cp, chr(cp)


def ranges(predicate):
    out, start, last = [], None, None
    for cp, c in chars():
        if predicate(c):
            if start is None or cp != last + 1:
                if start is not None:
                    out.append((start, last))
                start = cp
            last = cp
    if start is not None:
        out.append((start, last))
    return out


# Final sigma context, read back through str.lower() itself:
# ('AΣ' + c).lower() keeps σ  <=>  c is cased and not case-ignorable;
# ('A' + c + 'Σ').lower() ends in ς  <=>  c is case-ignorable or cased.
cased = ranges(lambda c: ('AΣ' + c).lower()[1] == 'σ')
ignorable_or_cased = set()
for lo, hi in ranges(lambda c: ('A' + c + 'Σ').lower()[-1] == 'ς'):
    ignorable_or_cased.update(range(lo, hi + 1))
cased_set = set()
for lo, hi in cased:
    cased_set.update(range(lo, hi + 1))
ignorable = ranges(lambda c: ord(c) in ignorable_or_cased and ord(c) not in cased_set)


def go_ranges(name, values):
    lines = [f'var {name} = [][2]rune{{']
    row = []
    for lo, hi in values:
        row.append(f'{{0x{lo:X}, 0x{hi:X}}}')
        if len(row) == 6:
            lines.append('\t' + ', '.join(row) + ',')
            row = []
    if row:
        lines.append('\t' + ', '.join(row) + ',')
    lines.append('}')
    return '\n'.join(lines)


def go_string(s):
    return '"' + ''.join(c if 0x20 <= ord(c) < 0x7f and c not in '"\\' else f'\\U{ord(c):08x}' for c in s) + '"'


lower = [(cp, c.lower()) for cp, c in chars() if c.lower() != c]

print(f'''// Code generated by testdata/gen_a05_unicode_tables.py from CPython
// {sys.version.split()[0]} (Unicode {unicodedata.unidata_version}); DO NOT EDIT.

package metrics

// pyLowerTable is c.lower() for every code point that changes ({len(lower)}).
var pyLowerTable = map[rune]string{{''')
for cp, value in lower:
    print(f'\t0x{cp:X}: {go_string(value)},')
print('}')
print()
print('// pyCasedRanges: cased and not case-ignorable (the final sigma rule only')
print('// asks whether a character that is not case-ignorable is cased).')
print(go_ranges('pyCasedRanges', cased))
print()
print('// pyCaseIgnorableRanges: case-ignorable (skipped by the final sigma rule).')
print(go_ranges('pyCaseIgnorableRanges', ignorable))
